/**
 * Represents the margin settings for each side.
 */
export interface Margin {
    /**
     * Sets the top margin in pixels.
     */
    top?: number;
    /**
     * Sets the right margin in pixels.
     */
    right?: number;
    /**
     * Sets the bottom margin in pixels.
     */
    bottom?: number;
    /**
     * Sets the left margin in pixels.
     */
    left?: number;
}
